for l in open('smooth-3900x-all-run.md'):
    m=re.match(r'^(\S+): 10 runs',l)
    if m: cur=m.group(1); yest[cur]=[]; continue
    m=re.match(r'^\s+\d+\s+\d+\s+([\d,\.]+) ns',l)
    if m and cur: yest[cur].append(float(m.group(1).replace(',','')))
def tm(v):
    s=sorted(v); k=s[1:5]; return sum(k)/4
print(f"{'bench':18}{'y.trim':>10}{'t.trim':>10}{'d%':>8}{'y.mean':>10}{'t.mean':>10}{'d%':>8} {'y.sd%':>7}{'t.sd%':>7} {'t.max/min':>9} {'lag1':>6}")
for b,rs in today.items():
    t=[r['mean_ns'] for r in rs]; y=yest.get(b,[])
    if not y: print(b,'no yesterday',len(t)); continue
    lag=[]
    for r in rs:
        x=r['block_mean_ns']; m=sum(x)/len(x); d=sum((a-m)**2 for a in x)
        if d>0: lag.append(sum((x[i]-m)*(x[i+1]-m) for i in range(len(x)-1))/d)
    yt,tt=tm(y),tm(t); ym,tmn=st.mean(y),st.mean(t)
    print(f"{b:18}{yt:10.3f}{tt:10.3f}{(tt/yt-1)*100:8.2f}{ym:10.3f}{tmn:10.3f}{(tmn/ym-1)*100:8.2f} {st.stdev(y)/ym*100:7.2f}{st.stdev(t)/tmn*100:7.2f} {max(t)/min(t):9.3f} {st.mean(lag):6.2f}")
print(len(today),'benches today;', sum(len(v) for v in today.values()),'records')
print('missing today:',[b for b in yest if b not in today])
EOF
