import json,statistics as st,datetime as dt
rows=[];per={}
for l in open('tmp/20260919T144009Z-4776-3900x.jsonl'):
    r=json.loads(l); x=r['block_mean_ns']; med=st.median(x)
    t0=dt.datetime.fromisoformat(r['t_start'].replace('Z','+00:00')).timestamp()
    n=0
    for i,v in enumerate(x):
        if v>med*1.05:
