    per.setdefault(r['bench'],[0,0]); per[r['bench']][0]+=n; per[r['bench']][1]+=len(x)
print('blocks >5% over their run median, per bench:')
for b,(n,t) in per.items(): print(f'  {b:18}{n:3}/{t}')
base=rows[0][0]
print('first 40 outlier blocks: t(s since first) bench run block ratio')
for t,b,r,i,q in rows[:40]: print(f'  {t-base:8.1f} {b:16} {r:2} {i} {q:.3f}')
print(len(rows),'total')
EOF
