1	//! Thread CPU-pinning helpers: `--pin-cpus` parsing, affinity
2	//! snapshot and restore, human-readable mask/plan summaries, and
3	//! the pool's placement, what its CPUs share.
4	
5	use std::collections::BTreeSet;
6	use std::path::Path;
7	
8	/// Parse a `--pin-cpus` value (comma-separated list with optional ranges)
9	/// into an ordered vector of CPU ids (the kernel's schedulable unit, sysfs
10	/// `cpuN`). Accepts forms like `"0,1"`, `"0-11"`, `"0,3-5,7"`. Duplicates
11	/// are preserved in the given order so oversubscription (`"0,0,0"`) works.
12	pub fn parse_cpus(spec: &str) -> Result<Vec<usize>, String> {
13	    let mut out = Vec::new();
14	    for part in spec.split(',').map(str::trim).filter(|s| !s.is_empty()) {
15	        match part.split_once('-') {
16	            None => out.push(
17	                part.parse::<usize>()
18	                    .map_err(|e| format!("invalid CPU id {part:?}: {e}"))?,
19	            ),
20	            Some((lo, hi)) => {
21	                let lo = lo
