fn no_such_profile(&self, spec: &str) -> String {
    let declared = if self.profiles.is_empty() {
        "none".to_string()
    } else {
        self.profiles
            .iter()
            .map(|(name, cpus)| format!("{name} = {cpus:?}"))
            .collect::<Vec<_>>()
            .join(", ")
    };
    format!(
        "{spec:?} is no declared profile and is not a CPU list.\n\
         A pin named rather than numbered is what lets one config serve every host, so the \
         names belong to the host: add a [profiles] table beside [freq] in \
         ~/.config/iiac-perf/config.toml, each entry a name and a CPU spec, as in \
         `smt = \"3,9\"` for the two threads of one core or `ccx = \"3,2\"` for two cores \
         sharing a last-level cache. `lscpu -e` shows which CPUs pair.\n\
         `{bin} setup-freq` creates that file when it is missing, and docs/config.md explains \
         the table. This host declares: {declared}.",
        bin = crate::BIN_NAME
    )
}

